"""Write the TypeScript list of desktop operations from the Python ``@operation`` registry."""

from __future__ import annotations

from pathlib import Path

from hardwareharness_backend.application import DESKTOP_METHODS

TARGET = Path(__file__).resolve().parents[2] / "packages/contracts/src/operations.generated.ts"


def render() -> str:
    lines = "".join(f'  "{name}",\n' for name in DESKTOP_METHODS)
    return (
        "// Generated by python/scripts/generate_operations.py from the Python @operation\n"
        "// registry. Do not edit; rerun the script after adding or renaming an operation.\n"
        f"export const DESKTOP_OPERATIONS = [\n{lines}] as const;\n\n"
        "export type DesktopOperation = (typeof DESKTOP_OPERATIONS)[number];\n"
    )


if __name__ == "__main__":
    TARGET.write_text(render(), encoding="utf-8", newline="\n")
